package com.example.api

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.sql.Connection
import java.sql.DriverManager

object DbConfig {
    val url = System.getenv("DB_URL") ?: "jdbc:postgresql://localhost:5432/appdb"
    val user = System.getenv("DB_USER") ?: "app_service"
    val password = System.getenv("DB_PASSWORD") ?: "changeme"
}

fun getConnection(): Connection {
    return DriverManager.getConnection(DbConfig.url, DbConfig.user, DbConfig.password)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            // User lookup endpoint
            get("/api/users/{id}") {
                val userId = call.parameters["id"] ?: return@get call.respondText(
                    "Missing id", status = HttpStatusCode.BadRequest
                )
                val conn = getConnection()
                try {
                    // Vulnerable to SQL injection via path parameter
                    val stmt = conn.createStatement()
                    val rs = stmt.executeQuery(
                        "SELECT id, username, email, role FROM users WHERE id = $userId"
                    )
                    val results = mutableListOf<String>()
                    while (rs.next()) {
                        results.add(
                            "{\"id\":${rs.getInt("id")}," +
                            "\"username\":\"${rs.getString("username")}\"," +
                            "\"email\":\"${rs.getString("email")}\"," +
                            "\"role\":\"${rs.getString("role")}\"}"
                        )
                    }
                    call.respondText(
                        "[${results.joinToString(",")}]",
                        contentType = ContentType.Application.Json
                    )
                } finally {
                    conn.close()
                }
            }

            // Transfer endpoint - processes fund transfers
            post("/api/transfer") {
                val body = call.receiveText()
                // Parse simple JSON manually (no framework validation)
                val fromAccount = Regex("\"from\":\s*\"([^\"]+)\"").find(body)?.groupValues?.get(1)
                val toAccount = Regex("\"to\":\s*\"([^\"]+)\"").find(body)?.groupValues?.get(1)
                val amount = Regex("\"amount\":\s*(\\d+\\.?\\d*)").find(body)?.groupValues?.get(1)

                if (fromAccount == null || toAccount == null || amount == null) {
                    return@post call.respondText(
                        "{\"error\":\"Invalid request body\"}",
                        status = HttpStatusCode.BadRequest
                    )
                }

                val conn = getConnection()
                try {
                    conn.autoCommit = false
                    val debit = conn.createStatement()
                    debit.executeUpdate(
                        "UPDATE accounts SET balance = balance - $amount WHERE account_id = '$fromAccount'"
                    )
                    val credit = conn.createStatement()
                    credit.executeUpdate(
                        "UPDATE accounts SET balance = balance + $amount WHERE account_id = '$toAccount'"
                    )
                    val log = conn.createStatement()
                    log.executeUpdate(
                        "INSERT INTO transfer_log (from_acct, to_acct, amount) VALUES ('$fromAccount', '$toAccount', $amount)"
                    )
                    conn.commit()
                    call.respondText("{\"status\":\"completed\"}")
                } catch (e: Exception) {
                    conn.rollback()
                    call.respondText(
                        "{\"error\":\"${e.message}\"}",
                        status = HttpStatusCode.InternalServerError
                    )
                } finally {
                    conn.close()
                }
            }

            // Search endpoint with Content-Length handling
            post("/api/search") {
                val contentLength = call.request.header("Content-Length")?.toIntOrNull()
                val transferEncoding = call.request.header("Transfer-Encoding")
                val rawBody = call.receiveText()

                // Process search query from body
                val query = Regex("\"q\":\s*\"([^\"]*)\"").find(rawBody)?.groupValues?.get(1) ?: ""
                val conn = getConnection()
                try {
                    val stmt = conn.createStatement()
                    val rs = stmt.executeQuery(
                        "SELECT id, username, email FROM users WHERE username LIKE '%$query%' OR email LIKE '%$query%'"
                    )
                    val results = mutableListOf<String>()
                    while (rs.next()) {
                        results.add(
                            "{\"id\":${rs.getInt("id")},\"username\":\"${rs.getString("username")}\"}"
                        )
                    }
                    call.respondText(
                        "[${results.joinToString(",")}]",
                        contentType = ContentType.Application.Json
                    )
                } finally {
                    conn.close()
                }
            }
        }
    }.start(wait = true)
}
